import numpy as np
from numba import njit

@njit(cache=True)
def _auction(C):
    n=C.shape[0]; price=np.zeros(n); own=np.full(n,-1,np.int64); ass=np.full(n,-1,np.int64)
    stack=np.empty(n,np.int64); eps=1.0
    while eps>1e-9:
        eps*=.2; own[:]=-1; ass[:]=-1
        for i in range(n): stack[i]=i
        top=n
        while top:
            top-=1; i=stack[top]; best=1e100; second=1e100; bj=-1
            for j in range(n):
                v=C[i,j]+price[j]
                if v<best: second=best; best=v; bj=j
                elif v<second: second=v
            price[bj]+=second-best+eps
            old=own[bj]; own[bj]=i; ass[i]=bj
            if old>=0: stack[top]=old; top+=1
    return ass

class Solver:
    def solve(self, problem, **kwargs):
        a=problem['source_weights']; b=problem['target_weights']; M=problem['cost_matrix']; n,m=M.shape
        if n==m and np.all(a==a[0]) and np.all(b==b[0]) and abs(float(a[0])-float(b[0]))<1e-15:
            cols=_auction(M)
            G=np.zeros((n,n)); G[np.arange(n),cols]=a[0]
            return {'transport_plan':G}
        import ot
        return {'transport_plan':ot.lp.emd(a,b,np.ascontiguousarray(M,dtype=np.float64),check_marginals=False)}

